import torch
import torch.nn as nn


class SARStem(nn.Module):
    """Adapter 2→3 dla 1. warstwy enkodera ResNet z ImageNetu."""

    def __init__(self, encoder: nn.Module):
        super().__init__()
        # 1×1 konwolucja miksuje VV+VH w 3 kanały — pretrenowane wagi enkodera nietknięte.
        self.adapt = nn.{{conv_layer}}(2, 3, kernel_size=1, bias=False)
        self.encoder = encoder

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(self.adapt(x))


def db_normalize(vv_db: torch.Tensor, vh_db: torch.Tensor) -> torch.Tensor:
    """Per-kanał z-score: empiryczne mu/sigma dla Europy w dB."""
    vv_mean, vv_std = {{vv_mean}}, 5.0
    vh_mean, vh_std = -18.0, 5.0
    vv = (vv_db - vv_mean) / vv_std
    vh = (vh_db - vh_mean) / vh_std
    # Zwróć tensor [B, C, H, W] — kanały na wymiarze {{stack_dim}}.
    return torch.stack([vv, vh], dim={{stack_dim}})
